import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/env.md","filePath":"reference/env.md","lastUpdated":1793093713000}'),r={name:"reference/env.md"};function n(c,t,i,h,s,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><p>Setup writes the ones you need. For the API brain they go in <code>~/.config/froghub/standalone.env</code>; keep secrets there rather than in the service unit.</p><h2 id="both-brains" tabindex="-1">Both brains <a class="header-anchor" href="#both-brains" aria-label="Permalink to &quot;Both brains&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>FROGHUB_PORT</code></td><td>The server&#39;s port on 127.0.0.1</td><td><code>8790</code></td></tr><tr><td><code>FROGHUB_BIG_MODEL</code></td><td>The bigger model <code>think_harder</code> hands hard questions to; <code>none</code> turns it off</td><td>Sonnet</td></tr><tr><td><code>FROGHUB_RECIPEAPI_KEY</code></td><td>A recipeapi.io key, overriding <code>~/.config/froghub/recipeapi.key</code></td><td></td></tr><tr><td><code>FROGHUB_MEALDB_KEY</code></td><td>Your own TheMealDB key</td><td><code>1</code> (the free one)</td></tr><tr><td><code>FROGHUB_FREESOUND_KEY</code></td><td>A Freesound API key, overriding <code>~/.config/froghub/freesound.key</code></td><td></td></tr></tbody></table><h2 id="the-claude-code-brain" tabindex="-1">The Claude Code brain <a class="header-anchor" href="#the-claude-code-brain" aria-label="Permalink to &quot;The Claude Code brain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>FROGHUB_TIMEOUT</code></td><td>Seconds to wait for a reply</td><td><code>45</code></td></tr><tr><td><code>FROGHUB_CLEAR_AFTER</code></td><td>Minutes of quiet before its conversation is cleared; <code>0</code> never</td><td><code>30</code></td></tr></tbody></table><h2 id="the-api-brain" tabindex="-1">The API brain <a class="header-anchor" href="#the-api-brain" aria-label="Permalink to &quot;The API brain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>ANTHROPIC_API_KEY</code></td><td>An Anthropic API key. Without one, it uses the OpenAI-compatible API</td><td></td></tr><tr><td><code>FROGHUB_MODEL</code></td><td>The Claude model</td><td><code>claude-haiku-5-5</code></td></tr><tr><td><code>FROGHUB_FALLBACK_URL</code></td><td>An OpenAI-compatible API&#39;s base URL, used without an Anthropic key or when it fails: LM Studio (<code>http://&lt;pc&gt;:1234/v1</code>), Ollama (<code>http://&lt;pc&gt;:11434/v1</code>) or OpenAI (<code>https://api.openai.com/v1</code>)</td><td></td></tr><tr><td><code>FROGHUB_FALLBACK_MODEL</code></td><td>The model name there, e.g. <code>qwen3:8b</code> on Ollama</td><td></td></tr><tr><td><code>FROGHUB_FALLBACK_KEY</code></td><td>Its API key, if it wants one (OpenAI does; LM Studio and Ollama don&#39;t)</td><td></td></tr><tr><td><code>FROGHUB_FALLBACK_TOOLS</code></td><td><code>basic</code> offers that model only reply, memory and web search, for a small model that gets lost among many tools</td><td>all of them</td></tr><tr><td><code>FROGHUB_SEARCH_URL</code></td><td>A <a href="https://docs.searxng.org" target="_blank" rel="noreferrer">SearXNG</a> instance for that model&#39;s web search, with <code>format=json</code> allowed</td><td>DuckDuckGo</td></tr><tr><td><code>FROGHUB_PROMPT</code></td><td>The assistant&#39;s rules</td><td><code>~/.config/froghub/assistant.md</code></td></tr><tr><td><code>FROGHUB_MEMORY</code></td><td>Its memory file</td><td><code>~/.config/froghub/memory.md</code></td></tr></tbody></table><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>FROGHUB_DIR</code></td><td>Where <code>install.sh</code> puts Frog Hub (and <code>upgrade.sh</code> and <code>remove.sh</code> look for it)</td><td><code>~/froghub</code></td></tr><tr><td><code>FROGHUB_REPO</code></td><td>The git repo <code>install.sh</code> fetches</td><td><code>https://github.com/froghub-assistant/froghub.git</code></td></tr><tr><td><code>VOICE_BIND</code></td><td>The address the voice containers listen on, the one Home Assistant reaches them on</td><td><code>127.0.0.1</code></td></tr></tbody></table>',10)])])}const f=e(r,[["render",n]]);export{u as __pageData,f as default};
